package main

import (
	"fmt"
)

func main() {
	var board [4][4]int
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			var c string
			fmt.Scan(&c)
			switch c {
			case "x":
				board[i][j] = 1
			case "o":
				board[i][j] = -3
			default:
				board[i][j] = 0
			}
		}
	}

	canWin := false
	for i := 0; !canWin && i < 4; i++ {
		for j := 0; j < 4; j++ {
			if board[i][j] >= 0 {
				sumHor, sumVer, sumDiaUp, sumDiaDown := 0, 0, 0, 0

				if j < 2 {
					sumHor = board[i][j] + board[i][j+1] + board[i][j+2]
				}
				if i < 2 {
					sumVer = board[i][j] + board[i+1][j] + board[i+2][j]
				}
				if i < 2 && j < 2 {
					sumDiaUp = board[i][j] + board[i+1][j+1] + board[i+2][j+2]
				}
				if i >= 2 && j < 2 {
					sumDiaDown = board[i][j] + board[i-1][j+1] + board[i-2][j+2]
				}

				if sumHor == 2 || sumVer == 2 || sumDiaUp == 2 || sumDiaDown == 2 {
					canWin = true
					break
				}
			}
		}
	}

	if canWin {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

